import * as React from 'react'
import { cva, type VariantProps } from 'class-variance-authority'

import { cn } from '@/src/shared/cn'

const inputVariants = cva(
  // #179: focus-visible:ring-ring/50 の /50 を外す（不透明にしないと 3:1 に届かない・
  // ui-ux-guidelines.md §7.3。tools/check_contrast.py の検査対象にするため CSS 変数側以外で opacity を持たせない）。
  'w-full min-w-0 rounded-lg border border-input bg-transparent text-base transition-colors outline-none file:inline-flex file:h-6 file:border-0 file:bg-transparent file:text-sm file:font-medium file:text-foreground placeholder:text-muted-foreground focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring disabled:pointer-events-none disabled:cursor-not-allowed disabled:bg-input/50 disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 dark:bg-input/30 dark:disabled:bg-input/80 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40',
  {
    variants: {
      size: {
        default: 'h-(--size-control-md) px-2.5 py-1',
        lg: 'h-(--size-control-lg) px-3',
        xl: 'h-(--size-control-xl) px-3',
      },
    },
    defaultVariants: {
      size: 'default',
    },
  },
)

function Input({
  className,
  type,
  size = 'default',
  ...props
}: Omit<React.ComponentProps<'input'>, 'size'> & VariantProps<typeof inputVariants>) {
  return (
    <input
      type={type}
      data-slot="input"
      data-size={size}
      className={cn(inputVariants({ size, className }))}
      {...props}
    />
  )
}

export { Input, inputVariants }
